using System.Runtime.InteropServices;
namespace LSE.AutoCADElectrical.Librarian;
public static class DiagnosticsService{
 public static string BuildReport(){var s=SettingsService.Load();var x=new List<string>{"LSE Librarian V1",RuntimeInformation.FrameworkDescription,"Assembly: "+typeof(DiagnosticsService).Assembly.Location,"Settings: "+SettingsService.SettingsPath,"Backup folder: "+s.BackupFolder,"Reference project: "+(s.ReferenceProjectPath.Length==0?"(none)":s.ReferenceProjectPath)};
  x.Add(Folder("Symbol library",s.SymbolLibraryFolder));x.Add(Folder("Stock symbol library",s.StockSymbolLibraryFolder));x.Add(Folder("Footprint library",s.FootprintLibraryFolder));x.Add(Folder("Stock footprint library",s.StockFootprintLibraryFolder));x.Add(Folder("User circuits",s.UserCircuitsFolder));x.Add(Folder("Icon menu folder",s.IconMenuFolder));x.Add(Folder("Images folder",s.ImagesFolder));
  x.Add(FileLine("Schematic icon menu",s.SchematicMenuPath));x.Add(FileLine("Panel icon menu",s.PanelMenuPath));x.Add(FileLine("Footprint lookup",s.FootprintLookupPath));x.Add(FileLine("Catalog",s.CatalogPath));x.Add(FileLine("Library standard JSON",s.LibraryStandardPath));x.Add(FileLine("Parts catalog workbook",s.NamingWorkbookPath));x.Add(FileLine("Naming standard JSON snapshot",s.NamingStandardPath));
  LibraryStandard? std=null;try{std=LibraryStandardService.Load(s.LibraryStandardPath);x.Add($"Library standard: PASS ({std.Kinds.Count} kinds, {std.SymbolFamilies.Count} symbol families, {std.Kinds.Values.Sum(k=>k.Categories.Count)} categories)");}catch(Exception ex){x.Add("Library standard: FAIL "+ex.Message);}
  foreach(var (name,path) in new[]{("Schematic icon menu",s.SchematicMenuPath),("Panel icon menu",s.PanelMenuPath)})if(File.Exists(path))try{var m=IconMenuService.Load(path);x.Add($"{name} parse: PASS ({m.Pages.Count} pages, {m.Pages.Sum(p=>p.Entries.Count(e=>e.IsEntry))} entries, {m.Encoding.EncodingName}, {(m.NewLine=="\r\n"?"CRLF":"LF")}, next page M{IconMenuService.NextPageNumber(m)})");if(std is not null)foreach(var k in std.Kinds.Values.Where(k=>s.MenuPathFor(k).Equals(path,StringComparison.OrdinalIgnoreCase))){var missing=k.MenuRootPages.Where(p=>m.Page(p) is null).ToList();x.Add($"  {k.DisplayName} root pages: "+(missing.Count==0?"PASS "+string.Join(", ",k.MenuRootPages):"MISSING "+string.Join(", ",missing)));}}catch(Exception ex){x.Add($"{name} parse: FAIL "+ex.Message);}
  if(Directory.Exists(s.ImagesFolder))try{x.Add($"Icon images: {Directory.EnumerateFiles(s.ImagesFolder,"*.png").Count()} png, {Directory.EnumerateFiles(s.ImagesFolder,"*.bmp").Count()} bmp; icon size setting {s.IconPixels} px");}catch{}
  if(File.Exists(s.FootprintLookupPath))try{x.Add($"Footprint lookup read: PASS ({new FootprintLookupService(s.FootprintLookupPath).GetTables().Count} manufacturer tables)");}catch(Exception ex){x.Add("Footprint lookup read: FAIL "+ex.Message);}
  try{var n=NamingWorkbookService.Load(s);x.Add((n.FromWorkbook?"Naming standard from workbook: PASS (":"Naming standard from JSON snapshot: PASS (")+NamingWorkbookService.Describe(n)+")");}catch(Exception ex){x.Add("Naming standard: FAIL "+ex.Message);}
  if(File.Exists(s.CatalogPath))try{var cs=new CatalogService(s.CatalogPath);x.Add($"Catalog read: PASS ({cs.GetTables().Count} family tables, part number column {CatalogTransactionService.PartColumn(s)}, backups in {CatalogTransactionService.BackupRoot(s)})");}catch(Exception ex){x.Add("Catalog read: FAIL "+ex.Message);}
  if(s.CatalogPath.Length>0&&File.Exists(IssuanceLock.PathFor(s.CatalogPath)))x.Add("Part number issuance lock file present: "+IssuanceLock.PathFor(s.CatalogPath)+" (another workstation is issuing a number, or a crash left it behind)");
  if(s.IconMenuFolder.Length>0&&File.Exists(LibraryLock.PathFor(s.IconMenuFolder)))x.Add("Library lock file present: "+LibraryLock.PathFor(s.IconMenuFolder)+" (another workstation is writing, or a crash left it behind)");
  x.Add("Recent items: "+s.RecentItems.Count);
  x.Add(FileLine("Company standards JSON (catalog browser)",s.CompanyStandardsPath)+(File.Exists(s.CompanyStandardsPath)?$" ({CompanyStandardsService.Load(s.CompanyStandardsPath).Count} records)":""));x.Add($"Catalog browser: block attribute for the part number {ComponentAssignService.PartAttribute(s)}, {s.Favorites.Count} favourites, {s.Recent.Count} recent assignments");
  x.Add(VaultCatalogService.Enabled(s)?"Catalog Vault checkout: ON ("+s.CatalogVaultPath+" on "+s.VaultServer+"/"+s.VaultName+"); "+Folder("Vault Explorer folder",s.VaultExplorerPath):"Catalog Vault checkout: off (Catalog path in Vault is blank)");
  return string.Join(Environment.NewLine,x);}
 static string Folder(string label,string path)=>label+": "+(path.Length==0?"(blank)":path+(Directory.Exists(path)?" (exists)":" (MISSING)"));
 static string FileLine(string label,string path)=>label+": "+(path.Length==0?"(blank)":path+(File.Exists(path)?" (exists)":" (MISSING)"));
}
